test('a missing, symlinked or unreadable location is reported unavailable per location; healthy locations still list; refresh recovers', async () => {
  await withTempRoot(async root => {
    await writeFile(join(root, 'pi', 'keep.md'), '')
    await writeFile(join(root, 'claude', 'other.md'), '')
    const app = createApp(fixtureLocations(root))
    try {
      const both = (await app.inject('/api/entries')).json()
      assert.deepEqual(both.locations.map((location: { status: string }) => location.status), ['available', 'available'])

      await rm(join(root, 'claude'), { recursive: true })
      const missing = await app.inject('/api/entries')
      assert.equal(missing.statusCode, 200)
      const missingBody = missing.json()
      assert.deepEqual(missingBody.entries, [{ source: 'Pi', locationId: PI, path: 'keep.md', kind: 'file' }])
      assert.equal(missingBody.locations[0].status, 'available')
      assert.equal(missingBody.locations[1].status, 'unavailable')
      assert.match(missingBody.locations[1].error, /does not exist|not found|missing/i)
      assert.ok(!missing.body.includes(root), 'no absolute path in the unavailable diagnostic')

      await symlink(join(root, 'pi'), join(root, 'claude'))
      const linked = (await app.inject('/api/entries')).json()
      assert.equal(linked.locations[1].status, 'unavailable')
      assert.match(linked.locations[1].error, /symbolic link/i)
      assert.equal(linked.entries.length, 1)

      await rm(join(root, 'claude'))
      await mkdir(join(root, 'claude'))
      await writeFile(join(root, 'claude', 'restored.md'), '')
      const restored = (await app.inject('/api/entries')).json()
      assert.deepEqual(restored.locations.map((location: { status: string }) => location.status), ['available', 'available'])
      assert.ok(restored.entries.some((entry: { locationId: string; path: string }) => entry.locationId === CLAUDE && entry.path === 'restored.md'))
      assert.equal((await app.inject(`/api/file?source=Claude&locationId=${CLAUDE}&path=restored.md`)).statusCode, 200)

      if (process.getuid?.() !== 0) {
        await chmod(join(root, 'pi'), 0o000)
        const unreadable = (await app.inject('/api/entries')).json()
        assert.equal(unreadable.locations[0].status, 'unavailable')
        assert.match(unreadable.locations[0].error, /readable|permission/i)
        assert.equal(unreadable.locations[1].status, 'available')
        await chmod(join(root, 'pi'), 0o755)
        const readable = (await app.inject('/api/entries')).json()
        assert.equal(readable.locations[0].status, 'available')
      }
    } finally { await app.close() }
  })
})
import { test, mock } from 'node:test'
import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import fs, { mkdtemp, mkdir, rename, rm, symlink, writeFile } from 'node:fs/promises'
import { createServer } from 'node:net'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { syncBuiltinESMExports } from 'node:module'
import { createApp } from './app.ts'
import { defaultFixtureRoot, fixtureLocations } from './config.ts'

const PI = 'pi-fixtures'
const CLAUDE = 'claude-fixtures'
const loc = (source: string) => (source === 'Pi' ? PI : CLAUDE)

function sha256(bytes: Buffer | string): string {
  return createHash('sha256').update(bytes).digest('hex')
}

async function withTempRoot(run: (root: string) => Promise<void>) {
  const root = await mkdtemp(join(tmpdir(), 'md-manager-file-test-'))
  try {
    await mkdir(join(root, 'pi'))
    await mkdir(join(root, 'claude'))
    await run(root)
  } finally {
    await rm(root, { recursive: true, force: true })
  }
}

/** Builds the query the same way the client must: URLSearchParams, never string concatenation. */
function fileUrl(params: Record<string, string> | Array<[string, string]>): string {
  return `/api/file?${new URLSearchParams(params).toString()}`
}

test('reads committed fixtures from both sources with exact content and a SHA-256 hash', async () => {
  const app = createApp(fixtureLocations(defaultFixtureRoot))
  try {
    const pi = await app.inject(fileUrl({ source: 'Pi', locationId: PI, path: 'skills/review.md' }))
    assert.equal(pi.statusCode, 200)
    assert.equal(pi.headers['cache-control'], 'no-store')
    assert.match(String(pi.headers['content-type']), /application\/json/)
    const content = '# Sample review skill\n\nCheck the result against the acceptance criteria.\n'
    assert.deepEqual(pi.json(), { source: 'Pi', locationId: PI, path: 'skills/review.md', content, hash: sha256(content) })

    // Duplicate filenames in different sources are distinct documents.
    const piWorkflow = (await app.inject(fileUrl({ source: 'Pi', locationId: PI, path: 'workflow.md' }))).json()
    const claudeWorkflow = (await app.inject(fileUrl({ source: 'Claude', locationId: CLAUDE, path: 'workflow.md' }))).json()
    assert.equal(piWorkflow.source, 'Pi')
    assert.equal(claudeWorkflow.source, 'Claude')
    assert.match(piWorkflow.content, /Sample Pi workflow/)
    assert.match(claudeWorkflow.content, /Sample Claude workflow/)
    assert.notEqual(piWorkflow.hash, claudeWorkflow.hash)

    const empty = await app.inject(fileUrl({ source: 'Claude', locationId: CLAUDE, path: 'empty.md' }))
    assert.equal(empty.statusCode, 200)
    assert.deepEqual(empty.json(), { source: 'Claude', locationId: CLAUDE, path: 'empty.md', content: '', hash: sha256('') })
    assert.equal(empty.json().hash, 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855')
  } finally { await app.close() }
})

test('preserves whitespace, CRLF and Unicode; hashes the bytes of the same read; uppercase .MD is eligible', async () => {
  await withTempRoot(async root => {
    const crlf = '  \r\n# Title\r\n\r\n\tindented\r\n\r\n  trailing  \r\n\r\n'
    await mkdir(join(root, 'pi', 'nested', 'deeper'), { recursive: true })
    await writeFile(join(root, 'pi', 'nested', 'deeper', 'NOTE.MD'), crlf)
    const unicode = '# Ünïcödé — 日本語 🚀\n'
    await writeFile(join(root, 'claude', 'ünï 日本.md'), unicode)
    const app = createApp(fixtureLocations(root))
    try {
      const nested = await app.inject(fileUrl({ source: 'Pi', locationId: PI, path: 'nested/deeper/NOTE.MD' }))
      assert.equal(nested.statusCode, 200)
      assert.equal(nested.json().content, crlf)
      assert.equal(nested.json().hash, sha256(Buffer.from(crlf, 'utf8')))

      const named = await app.inject(fileUrl({ source: 'Claude', locationId: CLAUDE, path: 'ünï 日本.md' }))
      assert.equal(named.statusCode, 200)
      assert.deepEqual(named.json(), { source: 'Claude', locationId: CLAUDE, path: 'ünï 日本.md', content: unicode, hash: sha256(Buffer.from(unicode, 'utf8')) })

      // Changing the bytes on disk changes the hash on the next read (no caching).
      await writeFile(join(root, 'pi', 'nested', 'deeper', 'NOTE.MD'), `${crlf}more`)
      const changed = await app.inject(fileUrl({ source: 'Pi', locationId: PI, path: 'nested/deeper/NOTE.MD' }))
      assert.equal(changed.json().content, `${crlf}more`)
      assert.notEqual(changed.json().hash, nested.json().hash)
      assert.equal(changed.json().hash, sha256(`${crlf}more`))
    } finally { await app.close() }
  })
})

