      assert.deepEqual(moved.json(), { op: 'move', source: 'Pi', locationId: PERSONAL, path: 'review/from-claude.md', destinationSource: 'Pi', destinationLocationId: PERSONAL, destinationPath: 'from-claude.md' })
    } finally { await app.close() }
