/** Wraps a name into short lines, preferring to break after separators. Full names stay in aria-labels. */
export function wrapLabel(name: string, maxChars = 14, maxLines = 3): string[] {
  const lines: string[] = []
  let rest = name
  while (rest.length > 0 && lines.length < maxLines) {
    if (rest.length <= maxChars) { lines.push(rest); rest = ''; break }
    let cut = -1
    for (let i = maxChars; i > 3; i -= 1) {
      if ('-_. '.includes(rest[i - 1])) { cut = i; break }
    }
    if (cut === -1) cut = maxChars
    lines.push(rest.slice(0, cut).trimEnd())
    rest = rest.slice(cut).trimStart()
  }
  if (rest.length > 0) lines[lines.length - 1] = `${lines[lines.length - 1].slice(0, maxChars - 1)}…`
  return lines
}
import { useState, type MouseEvent } from 'react'
import { breadcrumbsFor, breadcrumbsForFile, folderToPathname, type FileRef, type FolderRef } from './model.ts'

type Props = {
  selected: FolderRef | null
  /** When set, the trail leads to the file's folder and ends with the filename as a non-navigating item. */
  file?: FileRef | null
  onNavigate: (ref: FolderRef | null) => void
}

const MAX_VISIBLE = 4

/** Home / Source / folder … trail. Long trails collapse the middle behind an expandable “…” control. */
export function Breadcrumbs({ selected, file = null, onNavigate }: Props) {
  const [showAll, setShowAll] = useState(false)
  const crumbs = file ? breadcrumbsForFile(file) : breadcrumbsFor(selected)
  const collapsed = !showAll && crumbs.length > MAX_VISIBLE
  const hidden = collapsed ? crumbs.slice(1, crumbs.length - 2) : []
  const visible = collapsed ? [crumbs[0], ...crumbs.slice(crumbs.length - 2)] : crumbs

  const follow = (ref: FolderRef | null) => (event: MouseEvent<HTMLAnchorElement>) => {
    event.preventDefault()
    onNavigate(ref)
  }

  return (
    <nav className="breadcrumbs" aria-label="Breadcrumb">
      <ol>
        {visible.map((crumb, position) => {
          const isCurrent = position === visible.length - 1
          return (
            <li key={crumb.id}>
              {position === 1 && hidden.length > 0 && (
                <>
                  <button
                    type="button"
                    className="breadcrumb-ellipsis"
                    aria-expanded={false}
                    aria-label={`Show ${hidden.length} hidden breadcrumb ${hidden.length === 1 ? 'level' : 'levels'}`}
                    onClick={() => setShowAll(true)}
                  >
                    …
                  </button>
                  <span className="breadcrumb-separator" aria-hidden="true">/</span>
                </>
              )}
              {crumb.ref === undefined ? (
                <span className="breadcrumb-current" aria-current="page">{crumb.label}</span>
              ) : (
                <a href={folderToPathname(crumb.ref)} aria-current={isCurrent ? 'page' : undefined} onClick={follow(crumb.ref)}>
                  {crumb.label}
                </a>
              )}
              {!isCurrent && <span className="breadcrumb-separator" aria-hidden="true">/</span>}
            </li>
          )
        })}
      </ol>
    </nav>
  )
}
import { useLayoutEffect, useRef, type MutableRefObject } from 'react'
import { childCounts, childrenOf, describeCounts, SOURCES, type GraphNode, type TreeIndex } from './model.ts'

type Props = {
  index: TreeIndex
  expanded: ReadonlySet<string>
  selectedId: string | null
  /** Scroll position survives unmounting (graph mode, document view) through this owner-held store. */
  scrollRef: MutableRefObject<number>
  onSelect: (node: GraphNode) => void
  onOpenFile: (node: GraphNode) => void
  onToggleExpand: (node: GraphNode) => void
}

/** Accessible replacement for the graph: the same tree, expansion state and selection as nested lists. */
export function Outline({ index, expanded, selectedId, scrollRef, onSelect, onOpenFile, onToggleExpand }: Props) {
  const container = useRef<HTMLElement>(null)
  useLayoutEffect(() => {
    if (container.current) container.current.scrollTop = scrollRef.current
  }, [scrollRef])

  function renderFolder(node: GraphNode) {
    const isExpanded = expanded.has(node.id)
    const counts = childCounts(index, node.id)
    const children = childrenOf(index, node.id)
    return (
      <li key={node.id} className={`outline-item outline-${node.kind}`} data-node-id={node.id}>
        <div className="outline-row">
          <button
            type="button"
            className="outline-toggle"
            aria-expanded={isExpanded}
            aria-label={`${isExpanded ? 'Collapse' : 'Expand'} ${node.name}`}
            onClick={() => onToggleExpand(node)}
          >
            <svg viewBox="0 0 10 10" width="10" height="10" aria-hidden="true">
              <path d={isExpanded ? 'M 1 3 L 5 7 L 9 3' : 'M 3 1 L 7 5 L 3 9'} />
            </svg>
          </button>
          <button
            type="button"
            className="outline-name"
            aria-current={node.id === selectedId ? 'true' : undefined}
            onClick={() => onSelect(node)}
          >
            <span className="outline-icon" aria-hidden="true">{node.kind === 'source' ? '◎' : '▰'}</span>
            <span>{node.name}</span>
            <span className="visually-hidden">, {node.kind === 'source' ? 'source folder' : 'folder'}</span>
          </button>
          <span className="outline-counts">{describeCounts(counts)}</span>
        </div>
        {isExpanded && (
          <ul className="outline-list">
            {children.length === 0
              ? <li className="outline-empty">This folder is empty.</li>
              : children.map(child => (child.kind === 'file' ? renderFile(child) : renderFolder(child)))}
          </ul>
        )}
      </li>
    )
  }

  function renderFile(node: GraphNode) {
    return (
      <li key={node.id} className="outline-item outline-file" data-node-id={node.id}>
        <div className="outline-row">
          <button type="button" className="outline-name outline-file-name" onClick={() => onOpenFile(node)}>
            <span className="outline-icon" aria-hidden="true">▤</span>
            <span>{node.name}</span>
            <span className="visually-hidden">, Markdown file</span>
          </button>
        </div>
      </li>
    )
  }

  return (
    <nav
      className="outline"
      aria-label="Directory outline"
      ref={container}
      onScroll={event => { scrollRef.current = event.currentTarget.scrollTop }}
    >
      <ul className="outline-list outline-root">
        {SOURCES.map(source => renderFolder(index.nodes.get(source)!))}
      </ul>
    </nav>
  )
}
/** Client-side name checks mirroring the server's shared validator; the server remains authoritative. */
export function validateName(name: string, kind: 'file' | 'folder'): string | null {
  if (name.length === 0) return 'Enter a name.'
  if (name.includes('/') || name.includes('\\')) return 'The name cannot contain / or \\ (create nested folders one at a time).'
  if (name.includes('\0')) return 'The name contains an invalid character.'
  if (name === '.' || name === '..') return 'That name is reserved.'
  const markdown = name.toLowerCase().endsWith('.md')
  if (kind === 'file' && !markdown) return 'The file name must end in .md.'
  if (kind === 'folder' && markdown) return 'A folder name cannot end in .md.'
  return null
}
import { useMemo, useState, type FormEvent } from 'react'
import { nodeId, type FolderRef, type Source, type TreeIndex } from '../graph/model.ts'
import { Modal } from '../ui/Modal.tsx'
import { OperationError, performOperation, type MutationRequest, type MutationResponse } from './api.ts'
import { validateName } from './validate.ts'

/** What the user asked to do and to what. Folders use `kind: 'folder'`; a source root is a folder with path ''. */
export type OperationTarget =
  | { kind: 'folder'; ref: FolderRef }
  | { kind: 'file'; ref: { source: Source; path: string }; draftDirty: boolean }

export type Operation =
  | { op: 'create-file' | 'create-folder'; parent: FolderRef }
  | { op: 'rename' | 'move' | 'delete'; target: OperationTarget }
  | { op: 'copy'; target: Extract<OperationTarget, { kind: 'file' }> }

type Props = {
  operation: Operation
  index: TreeIndex
  onCancel: () => void
  onSuccess: (operation: Operation, response: MutationResponse) => void
}

function baseName(path: string): string {
  return path.slice(path.lastIndexOf('/') + 1)
}

function parentPath(path: string): string {
  const cut = path.lastIndexOf('/')
  return cut === -1 ? '' : path.slice(0, cut)
}

function describeFolder(ref: FolderRef): string {
  return ref.path ? `${ref.source} / ${ref.path}` : ref.source
}

function joinPath(parent: string, name: string): string {
  return parent ? `${parent}/${name}` : name
}

/** Folders of one source, in listing order, optionally excluding a subtree (a folder cannot move into itself). */
function folderOptions(index: TreeIndex, source: Source, exclude: string | null): FolderRef[] {
  const options: FolderRef[] = []
  for (const node of index.nodes.values()) {
    if (node.source !== source || node.kind === 'file') continue
    if (exclude !== null && (node.path === exclude || node.path.startsWith(`${exclude}/`))) continue
    options.push({ source, path: node.path })
  }
  return options.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0))
}

const TITLES: Record<Operation['op'], string> = {
  'create-file': 'New file', 'create-folder': 'New folder', rename: 'Rename', move: 'Move', delete: 'Delete', copy: 'Copy',
}
const SUBMIT: Record<Operation['op'], string> = {
  'create-file': 'Create', 'create-folder': 'Create', rename: 'Rename', move: 'Move', delete: 'Delete', copy: 'Copy',
}

