  assert.deepEqual(parsePathname(fileToPathname(ref)), { kind: 'file', ref })
  assert.deepEqual(parsePathname('/file/Pi/pi-personal/%252e%252e.md'), { kind: 'file', ref: { source: 'Pi', locationId: 'pi-personal', path: '%2e%2e.md' } })
