  assert.deepEqual(parsePathname('/file/Pi/pi-personal/'), { kind: 'malformed' })
  assert.deepEqual(parsePathname('/file/Pi'), { kind: 'malformed' })
  assert.deepEqual(parsePathname('/file'), { kind: 'malformed' })
