function parentPath(path: string): string {
  const cut = path.lastIndexOf('/')
  return cut === -1 ? '' : path.slice(0, cut)
}

function describeFolder(ref: FolderRef, index: TreeIndex): string {
  const parts = [ref.source]
  if (ref.locationId !== null) {
